static int oracle_winner(const gm_game *g)
{
    const int dirs[][2]={{0,1},{1,0},{1,1},{1,-1}};
    for(int r=0;r<GM_SIZE;++r) for(int c=0;c<GM_SIZE;++c)
        for(int d=0;d<4;++d) {
            int side=g->cells[r][c],ok=side!=0;
            for(int k=1;k<5 && ok;++k) {
                int rr=r+k*dirs[d][0],cc=c+k*dirs[d][1];
                if(rr<0 || rr>=GM_SIZE || cc<0 || cc>=GM_SIZE || g->cells[rr][cc]!=side) ok=0;
            }
            if(ok) return side;
        }
    return 0;
}
static void verify_state(const gm_game *g)
{
    int black=0,white=0;
    uint8_t visited[GM_SIZE][GM_SIZE]={{0}};
    for(int r=0;r<GM_SIZE;++r) for(int c=0;c<GM_SIZE;++c) {
        CHECK(g->cells[r][c]<=GM_WHITE);
        black+=g->cells[r][c]==GM_BLACK;white+=g->cells[r][c]==GM_WHITE;
    }
    CHECK(black+white==g->count);CHECK(black==white || black==white+1);
    CHECK(g->next==(g->count%2 ? GM_WHITE : GM_BLACK));
    for(int i=0;i<g->count;++i) {
        gm_move m=g->moves[i];CHECK(m.row>=0 && m.row<GM_SIZE && m.col>=0 && m.col<GM_SIZE);
        CHECK(!visited[m.row][m.col]);visited[m.row][m.col]=1;
        CHECK(g->cells[m.row][m.col]==(i%2 ? GM_WHITE : GM_BLACK));
    }
    int winner=oracle_winner(g);
    CHECK(g->result==(winner ? winner : g->count==GM_CAPACITY ? GM_DRAW : GM_EMPTY));
}
