        "HUST-GOMOKU 1\n0 1\n-1 0\nEND\n", "HUST-GOMOKU 1\n0 2\n1 1\n1 1\nEND\n",
        "HUST-GOMOKU 1\n0 1\n1 1\n", "HUST-GOMOKU 1\n0 0junk\nEND\n"};
    for(unsigned i=0;i<sizeof(invalid)/sizeof(invalid[0]);++i) {
        FILE *file=test_file();CHECK(file!=NULL);CHECK(fputs(invalid[i],file)>=0);rewind(file);
        gm_game before=g;int mode=7;CHECK(!gm_read_session(file,&g,&mode));CHECK(mode==7 && !memcmp(&g,&before,sizeof(g)));
        fclose(file);
    }
    FILE *file=test_file();CHECK(file!=NULL);gm_init(&g);CHECK(gm_play(&g,7,7));CHECK(gm_write_session(file,&g,1));
    CHECK(fseek(file,0,SEEK_END)==0);long length=ftell(file);CHECK(length>0);rewind(file);
    char data[4096];CHECK(fread(data,1,(size_t)length,file)==(size_t)length);data[length]=0;fclose(file);
    char *coordinate=strstr(data,"7 7\n");CHECK(coordinate!=NULL);coordinate[0]='8';
    file=test_file();CHECK(file!=NULL);CHECK(fputs(data,file)>=0);rewind(file);
    gm_game before=g;int mode=0;CHECK(!gm_read_session(file,&g,&mode));CHECK(!memcmp(&before,&g,sizeof(g)));fclose(file);
    file=test_file();CHECK(file!=NULL);g.cells[0][0]=GM_BLACK;CHECK(!gm_write_session(file,&g,1));CHECK(ftell(file)==0);fclose(file);
    gm_init(&g);CHECK(gm_play(&g,7,7));gm_app app;gm_app_restore(&app,&g,1);
    CHECK(app.ai.active && app.game.count==1);
    for(int i=0;i<20;++i)gm_app_tick(&app);
    CHECK(app.game.count==2 && app.game.next==GM_BLACK);
    gm_app_init(&app,0);cell_click(&app,7,7);
    unsigned revision=app.revision;click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);
    CHECK(app.pending_action==GM_CONFIRM_NEW && app.revision==revision && app.game.count==1);
    gm_app_set_time(&app,3000);
    CHECK(!app.pending_action && app.game.count==1 && app.revision==revision);
    click(&app,GM_BUTTON_X+10,GM_MODE_Y+10);cell_click(&app,8,8);
    CHECK(!app.pending_action && !app.human_ai && app.game.count==2);
    click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);click(&app,GM_BUTTON_X+10,GM_MODE_Y+10);
    CHECK(app.pending_action==GM_CONFIRM_MODE && !app.human_ai && app.game.count==2);
    /* Elapsed time, not callback count, governs a destructive-action deadline. */
    gm_app_init(&app,0);cell_click(&app,7,7);gm_app_set_time(&app,1000000);
    click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);
    for(int i=0;i<150;++i) gm_app_tick(&app);
    CHECK(app.pending_action==GM_CONFIRM_NEW && app.game.count==1);
    gm_app_set_time(&app,1002999);CHECK(app.pending_action==GM_CONFIRM_NEW);
    gm_app_set_time(&app,1003000);CHECK(app.pending_action==GM_CONFIRM_NONE);
    click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);CHECK(app.game.count==1 && app.pending_action==GM_CONFIRM_NEW);
    gm_app_set_time(&app,1009000);
    click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);CHECK(app.game.count==1 && app.pending_action==GM_CONFIRM_NEW);
    gm_app_set_time(&app,1010000);
    click(&app,GM_BUTTON_X+10,GM_NEW_Y+10);CHECK(app.game.count==0 && !app.pending_action);
}
