/* Linux-only storage integration. Run in the unique native build record folder. */
#include "../lab6_gomoku/storage.h"
#include <assert.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/wait.h>
#include <unistd.h>
int main(int argc,char **argv)
{
    assert(argc==2);char path[4096],lock_path[4096];
    assert(snprintf(path,sizeof(path),"%s/storage-test.txt",argv[1])<(int)sizeof(path));
    assert(snprintf(lock_path,sizeof(lock_path),"%s.lock",path)<(int)sizeof(lock_path));
    int lock=gm_storage_lock(path);assert(lock>=0);
    pid_t child=fork();assert(child>=0);
    if(child==0) {
        close(lock);int other=gm_storage_lock(path);
        if(other>=0) { close(other);_exit(1); }
        _exit(errno==EWOULDBLOCK || errno==EAGAIN ? 0 : 2);
    }
    int status;assert(waitpid(child,&status,0)==child);
    assert(WIFEXITED(status) && WEXITSTATUS(status)==0);
    gm_game g,loaded;gm_init(&g);gm_init(&loaded);int mode=-1;
    assert(gm_storage_load(path,&loaded,&mode)==0);
    assert(gm_storage_save(path,&g,1));assert(gm_storage_load(path,&loaded,&mode)==1 && mode==1 && loaded.count==0);
    assert(gm_play(&g,7,7));assert(gm_storage_save(path,&g,0));
    assert(gm_storage_load(path,&loaded,&mode)==1 && mode==0 && loaded.count==1 && loaded.cells[7][7]==GM_BLACK);
    gm_game invalid=g;invalid.cells[0][0]=GM_WHITE;
    assert(!gm_storage_save(path,&invalid,0));
    assert(gm_storage_load(path,&loaded,&mode)==1 && loaded.count==1 && !loaded.cells[0][0]);
    FILE *file=fopen(path,"wb");assert(file);assert(fputs("truncated save",file)>=0);assert(fclose(file)==0);
    gm_game before=loaded;int old_mode=mode;
    assert(gm_storage_load(path,&loaded,&mode)==-1);
    assert(!memcmp(&loaded,&before,sizeof(loaded)) && mode==old_mode);
    close(lock);assert(unlink(path)==0);assert(unlink(lock_path)==0);
    puts("PASS: Linux atomic replace/file+directory sync, invalid-save preservation, missing/truncated load and competing-process lock");
    return 0;
}

/* Actual Linux wrapper with injected syscalls. No device/board is accessed. */
#include "../common/common.h"
#include <linux/input.h>
#include <sys/ioctl.h>
#include <dirent.h>
#include <stdarg.h>
#include <assert.h>
static int current_slot=2,held_slot=-1,query_error=0,closed;
static struct input_event events[16];
static int event_count,event_next;
static int fake_open(const char *path,int flags,...)
{ (void)path;(void)flags;return 7; }
static int fake_close(int fd) { assert(fd==7);++closed;return 0; }
static int fake_ioctl(int fd,unsigned long request,...)
{
    assert(fd==7);va_list args;va_start(args,request);void *data=va_arg(args,void *);va_end(args);
    if(request==EVIOCGMTSLOTS((FINGER_NUM_MAX+1)*sizeof(int32_t))) {
        if(query_error) { errno=EIO;return -1; }
        int32_t *values=data,code=values[0];
        for(int i=0;i<FINGER_NUM_MAX;++i)
            values[i+1]=code==ABS_MT_TRACKING_ID ? (i==held_slot ? 42 : -1) :
                code==ABS_MT_POSITION_X ? 1000+i*100 : 2000+i*100;
        return 0;
    }
    struct input_absinfo *axis=data;memset(axis,0,sizeof(*axis));
    if(request==EVIOCGABS(ABS_MT_SLOT)) { axis->value=current_slot;axis->maximum=5; }
    else if(request==EVIOCGABS(ABS_MT_POSITION_X) || request==EVIOCGABS(ABS_MT_POSITION_Y)) axis->maximum=4096;
    else { errno=EINVAL;return -1; }
    return 0;
}
static ssize_t fake_read(int fd,void *data,size_t size)
{
    assert(fd==7 && size==sizeof(struct input_event));
    if(event_next==event_count) { errno=EAGAIN;return -1; }
    memcpy(data,&events[event_next++],size);return (ssize_t)size;
}
#define open fake_open
#define close fake_close
#define ioctl fake_ioctl
#define read fake_read
#include "../common/touch.c"
#undef open
#undef close
#undef ioctl
#undef read
static void event(int type,int code,int value)
{
    assert(event_count<16);struct input_event *e=&events[event_count++];
    memset(e,0,sizeof(*e));e->type=type;e->code=code;e->value=value;
}
int main(void)
{
    int x,y,finger;assert(touch_init("mock") == 7);
    /* Kernel slot 2 and both coordinates are unchanged: only new ID is sent. */
    event(EV_ABS,ABS_MT_TRACKING_ID,88);event(EV_SYN,SYN_REPORT,0);
    assert(touch_read(7,&x,&y,&finger)==TOUCH_PRESS && finger==2);
    assert(x==1200*1023/4096 && y==2200*599/4096);
    event(EV_ABS,ABS_MT_TRACKING_ID,-1);event(EV_SYN,SYN_REPORT,0);
    assert(touch_read(7,&x,&y,&finger)==TOUCH_RELEASE && finger==2);
    assert(touch_read(7,&x,&y,&finger)==TOUCH_NO_EVENT);
    held_slot=1;assert(touch_init("mock")==-1 && errno==EBUSY && closed==1);
    held_slot=-1;query_error=1;assert(touch_init("mock")==-1 && errno==EIO && closed==2);
    query_error=0;current_slot=5;assert(touch_init("mock")==7);
    event_count=event_next=0;
